        public Probe()
            : this(TestProjectNeo.RequireInstance().Client, CreateFactoryNode(), false, NeoValueOwnership.Session)
        {
        }

        private static NeoMemberClassWritable CreateFactoryNode()
        {
            var client = TestProjectNeo.RequireInstance().Client;
            return NeoGeneratedTypesSupport.CreateWritableClassValue(client, "fa17d649-6cfd-41d1-9f99-c5401dc0fa9a");
        }

        internal static Probe Create(NeoClient client, NeoMemberClass node)
        {
            return NeoGeneratedTypesSupport.GetOrCreateGeneratedClassValue<Probe>(client, node, static (factoryClient, factoryNode) =>
            {
                var clientClassId = factoryNode.ClassId;
                return clientClassId switch
                {
                    _ => new Probe(factoryClient, factoryNode, true, NeoValueOwnership.Asset),
                };
            });
        }

        internal static Probe CreateWritable(NeoClient client, NeoMemberClassWritable node)
        {
            return NeoGeneratedTypesSupport.GetOrCreateGeneratedClassValue<Probe>(client, node, static (factoryClient, factoryNode) =>
            {
                var clientClassId = factoryNode.ClassId;
                return clientClassId switch
                {
                    _ => new Probe(factoryClient, factoryNode, false, factoryNode.ownership),
                };
            });
        }

        internal static Probe? CreateDetached(NeoClient client, NeoDetachedValue value, bool saved)
        {
            return new Probe(client, value, !saved);
        }

        public Probe Clone()
        {
            return CreateWritable(client, NeoGeneratedTypesSupport.CloneClassValue(client, this));
        }

        IReadOnlyProbe IReadOnlyProbe.Clone()
        {
            return Clone();
        }

        public new bool TryWritable<TWritable>(out TWritable writable) where TWritable : class, INeoValueReference
        {
            return base.TryWritable(out writable);
        }

        public bool TryWritable(out Probe writable)
        {
            return TryWritable<Probe>(out writable);
        }

        public sealed class Fields
        {
            private Fields() {}
        }

        private IReadOnlyDictionary<INeoField, Func<string?>> LocalizedTextIdReaders()
        {
            return new Dictionary<INeoField, Func<string?>>
            {
            };
        }

        public string? GetLocalizedTextId<TField>(NeoField<TField> field)
        {
            var readers = LocalizedTextIdReaders();
            if (!readers.TryGetValue(field, out var reader))
            {
                throw new ArgumentException($"Field '{field.Key}' is not defined on this generated type.", nameof(field));
            }
            return reader();
        }

        private IReadOnlyDictionary<INeoField, Func<object?>> ChangedFieldReaders()
        {
            return new Dictionary<INeoField, Func<object?>>
            {
            };
        }

        public IDisposable OnChanged<TField>(NeoField<TField> field, Action<TField, NeoChangeSource> handler)
        {
            var readers = ChangedFieldReaders();
            if (!readers.TryGetValue(field, out var reader))
            {
                throw new ArgumentException($"Field '{field.Key}' is not defined on this generated type.", nameof(field));
            }
            return WatchField(field, handler, reader);
        }

        public IDisposable OnChanged(Action<NeoChangedArgs<Fields>> handler)
        {
            return WatchChanges(ChangedFieldReaders(), handler);
        }
    }
